                    "title": "Originalt ID"
                },
                "poster": {
                    "type": "boolean",
                    "title": "Plakat"
                },
                "stagename": {
                    "type": "string",
                    "title": "Scene"
                },
                "composer": {
                    "type": "string",
                    "title": "Komponist"
                },
                "translater": {
                    "type": "string",
                    "title": "Overs\u00e6tter"
                },
                "publisher": {
                    "type": "string",
                    "title": "Udgiver"
                },
                "programme": {
                    "type": "boolean",
                    "title": "Program"
                },
                "season": {
                    "type": "string",
                    "title": "S\u00e6son"
                },
                "playwright": {
                    "type": "string",
                    "title": "Forfatter"
                },
                "director": {
                    "type": "string",
                    "title": "Instrukt\u00f8r"
                },
                "scenographer": {
                    "type": "string",
                    "title": "Scenograf"
                }
            }
        }
    }
}

{
    "id": "https://almanak.github.io/schemas/people.aarhusteater.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "people.aarhusteater",
    "description": "Schema for all personnel resources at Aarhus Teater.",
    "type": "object",
    "_meta": {
        "indexProperties": [
            "id",
            "domain",
            "schema",
            "occupation",
            "date_from",
            "date_to"
        ],
        "systemProperties": [
            "uuid",
            "id",
            "domain",
            "schema",
            "scheme",
            "created",
            "created_by",
            "updated",
            "updated_by",
            "status"
        ],
        "fulltextProperties": [
            "description"
        ],
        "autocompleteProperties": [
            "display_label"
        ]
    },
    "required": [
        "lastnames",
        "gender"
    ],
    "properties": {
        "uuid": {
            "type": "string",
            "title": "Universal unique identifier",
            "description": "UUID1. Assigned by system",
            "pattern": "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
        },
        "id": {
            "type": "string",
            "title": "Resourcespecifik ID",
            "description": "9-cifret l\u00f8benummer semi-specifik for resourcetypen. Assigned by system",
            "maxLength": 9,
            "pattern": "^[0-9]{9}$"
        },
        "domain": {
            "type": "string",
            "enum": [
                "records",
                "people",
                "organisations",
                "families",
                "events",
                "places",
                "concepts",
                "things"
            ],
            "title": "Resourcetype",
            "description": "S\u00e6ttes kun n\u00e5r der v\u00e6lges skema til oprettelse. Ellers fastsat."
        },
        "schema": {
            "type": "string",
            "title": "Skema",
            "description": "S\u00e6ttes kun n\u00e5r der v\u00e6lges skema til oprettelse. Ellers fastsat."
        },
        "created": {
            "type": "string",
            "format": "date-time",
            "title": "Skabt",
            "description": "Datetime for skabelse af metadata-ressourcen"
        },
        "created_by": {
            "type": "string",
            "maxLength": 255,
            "title": "Skabt af",
            "description": "Brugernavn/ID p\u00e5 skaber/oploader af metadata-ressourcen"
